using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;
using Activator = Mutagen.Bethesda.Starfield.Activator;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Components' reflection subrecords (REFL, PTCL, PCCC) are Reflection objects: exact bytes plus the FormIDs inside
// them as FormLinks (effect sequence parents, lights, particle define collections). Whole records from Starfield.esm,
// both readers, written back byte for byte.
public class ReflectionComponentTests
{
    // WPNShipLaserAImpact (005A47:Starfield.esm)
    private const string Impact = "";

    // Debug_TestBurstActivator (00A17E:Starfield.esm), without its localized FULL
    private const string BurstActivator = "";

    // LinnaeusIV-bPlanetData (05E080:Starfield.esm): its EDID and Houdini data component (PCCC, 4,101 bytes)
    private const string PlanetHoudini = "";

    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    [Fact]
    public void Impact_EffectSequenceAndParticleComponents()
    {
        foreach (var ipct in ReadBoth<IImpactGetter>(Record("IPCT", Hex(Impact)), f => Mutagen.Bethesda.Starfield.Impact.CreateFromBinary(f), (s, p) => ImpactBinaryOverlay.ImpactFactory(s, p)))
        {
            // ShipFX_ImpactBallisticLight_FXS (0B264B:Starfield.esm)
            var sequence = ipct.Components.OfType<IEffectSequenceComponentGetter>().Single().Reflection;
            sequence.ShouldHaveFormIds(0x0B264B);
            sequence.RootObject().Class.Name.ShouldBe("BGSEffectSequenceFormComponent");
            // ShipWeaponImpact_PDC (13D923:Starfield.esm)
            var particles = ipct.Components.OfType<IParticleSystemComponentGetter>().Single().Reflection;
            particles.ShouldHaveFormIds(0x13D923);
            particles.RootObject().Class.Name.ShouldBe("ParticleFormComponent");
            ipct.EnumerateFormLinks().Select(l => l.FormKey.ID).ShouldContain(0x13D923u);
            WritesBack(ipct, Impact);
        }
    }

    [Fact]
    public void Activator_LightAttachment()
    {
        foreach (var acti in ReadBoth<IActivatorGetter>(Record("ACTI", Hex(BurstActivator)), f => Activator.CreateFromBinary(f), (s, p) => ActivatorBinaryOverlay.ActivatorFactory(s, p)))
        {
            // DebugTestBurstFX (211B99:Starfield.esm)
            acti.Components.OfType<IEffectSequenceComponentGetter>().Single().Reflection.ShouldHaveFormIds(0x211B99);
            // _RENAME_TestFXAnimatedLight (14AF4E:Starfield.esm)
            acti.Components.OfType<ILightAttachmentFormComponentGetter>().Single().Reflection.ShouldHaveFormIds(0x14AF4E);
            acti.Components.OfType<IParticleSystemComponentGetter>().Single().Reflection.ShouldHaveFormIds();
            WritesBack(acti, BurstActivator);
        }
    }

    [Fact]
    public void Planet_HoudiniData()
    {
        foreach (var pndt in ReadBoth<IPlanetGetter>(Record("PNDT", Hex(PlanetHoudini)), f => Planet.CreateFromBinary(f), (s, p) => PlanetBinaryOverlay.PlanetFactory(s, p)))
        {
            var houdini = pndt.Components.OfType<IHoudiniDataComponentGetter>().Single().Reflection;
            houdini.ShouldHaveFormIds();
            houdini.RootObject().Class.Name.ShouldBe("HoudiniDataComponent");
            houdini!.Data.Length.ShouldBe(4101);
            // The planet writes its required body subrecords (BDST and on) after these; the part read back is byte-identical
            var written = GameConstants.Starfield.MajorRecord(Write(w => pndt.WriteToBinary(w))).Content.ToArray();
            written.AsSpan(0, Hex(PlanetHoudini).Length).ToArray().ShouldBe(Hex(PlanetHoudini));
        }
    }
}
